import type {
  AnalyticsProvider,
  OwnershipMethod,
  ProjectGoal,
  ProjectStep,
} from "@/lib/db/schema/project";
import { parseWebsite, isRepoName } from "@/lib/onboarding/website";

export { parseWebsite, isRepoName };
export type { AnalyticsProvider, OwnershipMethod, ProjectGoal };

export const onboardingSteps = [
  {
    id: "website",
    label: "YOUR WEBSITE",
    title: "Start with your website.",
    description: "One website. One agent. A continuous loop of better.",
  },
  {
    id: "analytics",
    label: "ANALYTICS",
    title: "Where’s your visitor data?",
    description: "Choose the analytics platform you use.",
  },
  {
    id: "github",
    label: "REPOSITORY",
    title: "Give your agent a place to work.",
    description: "Choose the GitHub repository for this website.",
  },
  {
    id: "goal",
    label: "YOUR GOAL",
    title: "Ready for less friction.",
    description: "Pick a goal and review your setup.",
  },
] as const;

export const analyticsChoices: { id: AnalyticsProvider; label: string }[] = [
  { id: "posthog", label: "PostHog" },
  { id: "mixpanel", label: "Mixpanel" },
  { id: "amplitude", label: "Amplitude" },
];

export const goalChoices: { id: ProjectGoal; label: string }[] = [
  { id: "signup_conversion", label: "Signup conversion" },
  { id: "checkout_completion", label: "Checkout completion" },
  { id: "contact_form", label: "Contact form submissions" },
];

export function uiStepIndex(step: ProjectStep) {
  if (step === "analytics") return 1;
  if (step === "github") return 2;
  if (step === "goal" || step === "done") return 3;
  return 0;
}

export function analyticsLabel(id: AnalyticsProvider) {
  return analyticsChoices.find((choice) => choice.id === id)?.label ?? id;
}

export function goalLabel(id: ProjectGoal) {
  return goalChoices.find((choice) => choice.id === id)?.label ?? id;
}

import type {
  OnboardingAction,
  OnboardingDraft,
} from "@/lib/onboarding/draft";

export async function postOnboarding(body: OnboardingAction) {
  const response = await fetch("/api/onboarding", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(body),
  });

  let payload: { draft?: OnboardingDraft; error?: string } = {};
  try {
    payload = (await response.json()) as typeof payload;
  } catch {
    payload = {};
  }

  if (!response.ok || !payload.draft) {
    const error = new Error(payload.error ?? "Couldn't save your progress.") as Error & {
      draft?: OnboardingDraft;
    };
    error.draft = payload.draft;
    throw error;
  }

  return payload.draft;
}

